package com.worldgenv2.density;

import com.worldgenv2.positions.PositionsProvider;

import java.util.List;
import java.util.Objects;

/**
 * Calculates cellular Voronoi distance to the closest point generated by a {@link PositionsProvider}.
 */
public final class PositionsCellNoiseDensity implements DensityFunction {

    private final PositionsProvider positionsProvider;
    private final float searchRadius;
    private final float maxDistance;

    public PositionsCellNoiseDensity(PositionsProvider positionsProvider, float searchRadius, float maxDistance) {
        this.positionsProvider = Objects.requireNonNull(positionsProvider, "positionsProvider");
        this.searchRadius = Math.max(1.0f, searchRadius);
        this.maxDistance = Math.max(1.0f, maxDistance);
    }

    public PositionsProvider positionsProvider() {
        return positionsProvider;
    }

    public float searchRadius() {
        return searchRadius;
    }

    public float maxDistance() {
        return maxDistance;
    }

    @Override
    public float compute(float x, float y, float z) {
        double minX = x - searchRadius;
        double maxX = x + searchRadius;
        double minY = y - searchRadius;
        double maxY = y + searchRadius;
        double minZ = z - searchRadius;
        double maxZ = z + searchRadius;

        java.util.List<com.worldgenv2.vector.Vec3d> points = positionsProvider.getPositions(minX, minY, minZ, maxX, maxY, maxZ);
        if (points.isEmpty()) {
            return 1.0f;
        }

        double minSq = Double.MAX_VALUE;
        for (com.worldgenv2.vector.Vec3d p : points) {
            double dx = p.x() - x;
            double dy = p.y() - y;
            double dz = p.z() - z;
            double distSq = dx * dx + dy * dy + dz * dz;
            if (distSq < minSq) {
                minSq = distSq;
            }
        }

        float dist = (float) Math.sqrt(minSq);
        float norm = Math.clamp(dist / maxDistance, 0.0f, 1.0f);
        return norm * 2.0f - 1.0f;
    }

    @Override
    public void computeColumn(float x, float z, int minY, int maxY, float[] out) {
        int height = maxY - minY;
        for (int i = 0; i < height; i++) {
            out[i] = compute(x, minY + i, z);
        }
    }
}
